// -----------------------------------------------------------------------------
// bob_clb - the cluster: 4 logic elements (LUT6, fracturable, 2 FFs), 16 inputs,
// 8 outputs, a full crossbar of 24:1 muxes per element input.
// M22: LUT contents and crossbar in CFGLUT5 (152 per CLB), loaded by
// hw/src/core/lut_loader.v from the CLB's L-frames: lce[f] shifts frame f
// (INIT frames 0..1, crossbar frames 2..2), lcdi_* are the shared expander's
// bits (lut_expand.v). cfg: the element flags, element e at [12e +: 12] (BOB_ELE_*).
// -----------------------------------------------------------------------------
/* verilator lint_off DECLFILENAME */
module bob_clb (
    input  wire              clk, gce, gsr, gwe, ce, sr, cin,
    input  wire [15:0]       i,
    input  wire [47:0]       cfg,
