    /* verilator lint_off UNUSEDSIGNAL */
    wire _unused = &{1'b0, lcdi_init, lcdi_x};     // not every slot is used by every CLB frame
    /* verilator lint_on UNUSEDSIGNAL */
    wire [4:0] cy;
    assign cy[0] = cin;
    assign cout  = cy[4];
    // element 0: INIT in L-frame 0 slot 0
    wire [5:0] x0;
    lxmux #(.S(24)) m0_0 (.in({o[7], o[6], o[5], o[4], o[3], o[2], o[1], o[0], i[15], i[14], i[13], i[12], i[11], i[10], i[9], i[8], i[7], i[6], i[5], i[4], i[3], i[2], i[1], i[0]}), .lck(lck), .lce(lce[2]), .lcdi(lcdi_x[0 +: 6]), .o(x0[0]));
