    lxmux #(.S(24)) m0_3 (.in({o[7], o[6], o[5], o[4], o[3], o[2], o[1], o[0], i[15], i[14], i[13], i[12], i[11], i[10], i[9], i[8], i[7], i[6], i[5], i[4], i[3], i[2], i[1], i[0]}), .lck(lck), .lce(lce[2]), .lcdi(lcdi_x[18 +: 6]), .o(x0[3]));
    lxmux #(.S(24)) m0_4 (.in({o[7], o[6], o[5], o[4], o[3], o[2], o[1], o[0], i[15], i[14], i[13], i[12], i[11], i[10], i[9], i[8], i[7], i[6], i[5], i[4], i[3], i[2], i[1], i[0]}), .lck(lck), .lce(lce[2]), .lcdi(lcdi_x[24 +: 6]), .o(x0[4]));
    lxmux #(.S(24)) m0_5 (.in({o[7], o[6], o[5], o[4], o[3], o[2], o[1], o[0], i[15], i[14], i[13], i[12], i[11], i[10], i[9], i[8], i[7], i[6], i[5], i[4], i[3], i[2], i[1], i[0]}), .lck(lck), .lce(lce[2]), .lcdi(lcdi_x[30 +: 6]), .o(x0[5]));
